// Remote exec helper for the LIVE Soul Pilates box (51.79.226.200).
// Mirrors lib/sftp.ts credential handling: decrypt Server.rootPasswordEnc with
// the key derived from AUTH_SECRET (lib/crypto-box.ts), connect as root:22.
// Usage: node remote.mjs '<shell command>'
import { readFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { createDecipheriv, scryptSync } from "node:crypto";
import { Client } from "/opt/nxeon/node_modules/ssh2/lib/index.js";

const HOST = "51.79.226.200";
const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";

function envVal(key) {
  const line = readFileSync("/opt/nxeon/.env", "utf8")
    .split("\n")
    .find((l) => l.startsWith(key + "="));
  if (!line) throw new Error(key + " not found in .env");
  return line.slice(key.length + 1);
}

function deriveKey(secret) {
  return scryptSync(secret, "nxeon-byok", 32);
}
function decryptSecret(enc, secret) {
  const [ivB64, tagB64, dataB64] = enc.split(":");
  const decipher = createDecipheriv("aes-256-gcm", deriveKey(secret), Buffer.from(ivB64, "base64"));
  decipher.setAuthTag(Buffer.from(tagB64, "base64"));
  const dec = Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]);
  return dec.toString("utf8");
}

const AUTH_SECRET = envVal("AUTH_SECRET");
