15	function execOnce(conn: Client, command: string, timeoutMs = 120_000): Promise<{ code: number | null; stdout: string; stderr: string }> {
16	  return new Promise((resolve, reject) => {
17	    conn.exec(command, (err, stream) => {
18	      if (err) return reject(err);
19	      let stdout = "", stderr = "", settled = false;
20	      const timer = setTimeout(() => { if (!settled) { settled = true; try { stream.close(); } catch {} reject(new Error("timeout")); } }, timeoutMs);
21	      stream.on("close", (code: number | null) => { if (!settled) { settled = true; clearTimeout(timer); resolve({ code, stdout, stderr }); } })
22	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
23	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
24	    });
25	  });
26	}
