42	    const t = setTimeout(() => { try { conn.end(); } catch {} reject(new Error("connect timeout")); }, 15000);
43	    conn.on("ready", () => { clearTimeout(t); resolve(); })
44	      .on("error", (e) => { clearTimeout(t); reject(e); })
45	      .connect({ host: target.host, port: target.port, username: "root", password, readyTimeout: 15000 });
46	  });
47	  try {
48	    const idc = await execOnce(conn, "hostname -I");
49	    if (!idc.stdout.includes(REQUIRED_IP)) {
50	      throw new Error(`SAFETY ABORT: hostname -I did not contain ${REQUIRED_IP}. Got: ${idc.stdout.trim()}`);
51	    }
