// Decrypt Server.rootPasswordEnc and write ONLY the plaintext to argv[2] (0600).
// Never prints the password. Run from /opt/nxeon so @prisma/client resolves.
import 'dotenv/config';
import { scryptSync, createDecipheriv } from 'node:crypto';
import { writeFileSync, chmodSync } from 'node:fs';
import { PrismaClient } from '@prisma/client';

function deriveKey() { return scryptSync(process.env.AUTH_SECRET, 'nxeon-byok', 32); }
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [iv, tag, data] = enc.split(':');
    const d = createDecipheriv('aes-256-gcm', deriveKey(), Buffer.from(iv, 'base64'));
    d.setAuthTag(Buffer.from(tag, 'base64'));
    return Buffer.concat([d.update(Buffer.from(data, 'base64')), d.final()]).toString('utf8');
  } catch { return null; }
}
const prisma = new PrismaClient();
const s = await prisma.server.findUnique({
  where: { id: 'cmsc9l72y000ghl7iyd87u5ja' },
  select: { ipAddress: true, sshPort: true, rootPassword: true, rootPasswordEnc: true },
});
await prisma.$disconnect();
if (!s) { console.error('server not found'); process.exit(1); }
const pw = decryptSecret(s.rootPasswordEnc) ?? s.rootPassword;
if (!pw) { console.error('no password'); process.exit(2); }
writeFileSync(process.argv[2], pw, { mode: 0o600 });
chmodSync(process.argv[2], 0o600);
console.log(JSON.stringify({ ip: s.ipAddress, port: s.sshPort || 22, ok: true, pwLen: pw.length }));

// No external deps. Reads AUTH_SECRET + DATABASE_URL from /opt/nxeon/.env,
// fetches rootPasswordEnc via psql, decrypts (AES-256-GCM, key = scrypt(AUTH_SECRET,"nxeon-byok")),
// writes ONLY plaintext to argv[2] (0600). Never prints the password.
import { scryptSync, createDecipheriv } from 'node:crypto';
import { writeFileSync } from 'node:fs';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

function envVal(key) {
  const line = readFileSync('/opt/nxeon/.env', 'utf8').split('\n').find(l => l.startsWith(key + '='));
  if (!line) throw new Error(key + ' missing');
  let v = line.slice(key.length + 1).trim();
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
  return v;
}
const AUTH_SECRET = envVal('AUTH_SECRET');
const DATABASE_URL = envVal('DATABASE_URL');
const enc = execFileSync('psql', [DATABASE_URL, '-t', '-A', '-c',
  `SELECT "rootPasswordEnc" FROM "Server" WHERE id='cmsc9l72y000ghl7iyd87u5ja';`], { encoding: 'utf8' }).trim();
if (!enc) throw new Error('no rootPasswordEnc');
const [iv, tag, data] = enc.split(':');
const d = createDecipheriv('aes-256-gcm', scryptSync(AUTH_SECRET, 'nxeon-byok', 32), Buffer.from(iv, 'base64'));
d.setAuthTag(Buffer.from(tag, 'base64'));
const pw = Buffer.concat([d.update(Buffer.from(data, 'base64')), d.final()]).toString('utf8');
writeFileSync(process.argv[2], pw, { mode: 0o600 });
console.log(JSON.stringify({ ok: true, pwLen: pw.length }));

