public async Task<MonthlyWashout> ComputeMonthlyWashoutAsync(int month, int year)
{
    // ── Lock check ───────────────────────────────────────────────────────
    // Once admin clicks "Lock month" (P2-S07) we refuse to recompute. The
    // bank transfers have likely already gone out at that point and a silent
    // re-shape would break the audit trail.
    var existing = await _washouts
        .Find(w => w.Year == year && w.Month == month)
        .FirstOrDefaultAsync();
    if (existing is { Locked: true })
    {
        throw new InvalidOperationException(
            $"Washout for {year}-{month:D2} is locked and cannot be recomputed. Unlock it first.");
    }

    var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
    var end = start.AddMonths(1).AddTicks(-1);

    // ── Revenue (invoices + their payments for the per-method split) ─────
    // VOIDED invoices are cancelled and must never count toward revenue.
    var invoices = await _invoices
        .Find(i => i.IssueDate >= start && i.IssueDate <= end && i.Status != "VOIDED")
        .ToListAsync();

    // Cash-basis revenue (studio policy): count only money ACTUALLY received in
    // the period on these non-voided invoices — never the full invoiced amount.
    // Unpaid package purchases and the uncollected balance of deposit bookings
    // stay out of revenue until the cash arrives, so no-shows and unpaid
    // balances can't overstate income. Matched by both invoice scope AND
    // payment date so late payments land in the month the money came in.
    var invoiceIds = invoices.Where(i => i.Id != null).Select(i => i.Id!).ToList();
    var monthPayments = invoiceIds.Count == 0
        ? new List<Payment>()
        : await _payments
            .Find(p => invoiceIds.Contains(p.InvoiceId) && p.PaymentDate >= start && p.PaymentDate <= end)
            .ToListAsync();

    var totalSales = monthPayments.Sum(p => p.AmountPaid);
    var revenueByMethod = monthPayments
        .GroupBy(p => string.IsNullOrEmpty(p.PaymentMethod) ? "UNKNOWN" : p.PaymentMethod)
        .ToDictionary(g => g.Key, g => g.Sum(p => p.AmountPaid));
    var revenueByCategory = await ComputeRevenueByCategoryAsync(invoices, monthPayments);

    // ── Costs ────────────────────────────────────────────────────────────
    var monthExpenses = await GetExpensesAsync(month, year);
    // Pool-funded expenses (MARKETING / SAVINGS FundSource) are NOT part of
    // this month's operating FixedExpenses — they draw from the cumulative
    // reserve pool balance instead. Only OPERATIONS (and legacy null/empty)
    // expenses count against the monthly P&L.
    var operationsExpenses = monthExpenses
        .Where(e => string.IsNullOrEmpty(e.FundSource) || e.FundSource == "OPERATIONS")
        .ToList();
    // Break salaries (from the Salaries editor) out of fixed expenses so the
    // washout shows them on their own line — same as the studio's P&L. They
    // stay part of total costs; only the display grouping changes.
    var totalSalaries = operationsExpenses
        .Where(e => e.SalaryForStaffId != null)
        .Sum(e => e.Amount);
    var totalFixed = operationsExpenses.Sum(e => e.Amount) - totalSalaries;

    // ── P2-S08: Stripe routing decision ────────────────────────
    // When OWNER_ROUTED, the studio chooses one owner's bank to absorb Stripe
    // fees. The sheet semantics: pool is computed against gross (fees un-deducted
    // from FixedExpenses), then the full fee is deducted from the chosen owner's
    // distribution. Net effect: every owner gets a tiny equity bump from the
    // bigger pool, the chosen owner's bump is offset by the full fee.
    var routing = await ResolveStripeRoutingAsync(monthExpenses);
    if (routing.IsRouted)
    {
        totalFixed -= routing.FeeAmount;
    }

    var allCapital = await _capital.Find(c => c.PurchaseDate <= end).ToListAsync();
    decimal totalDepreciation = 0;
    foreach (var cap in allCapital)
    {
        var monthsSince = ((year - cap.PurchaseDate.Year) * 12) + month - cap.PurchaseDate.Month;
        if (monthsSince >= 0 && monthsSince < cap.DepreciationMonths)
        {
            totalDepreciation += cap.MonthlyDepreciationAmount;
        }
    }

    // ── Auto-trigger payroll calculation ────────────────────────────────
    // Previously, the admin had to manually run payroll BEFORE computing the
    // washout. Now we automatically calculate payroll for the month so that
    // the PayrollRun is guaranteed to exist with fresh data.
    await _payrollService.CalculatePayrollAsync(start, end);

    var monthPayrolls = await _payrolls.Find(p => p.PeriodEnd >= start && p.PeriodEnd <= end).ToListAsync();
    await _receptionistKpi.ApplyReceptionistCompToPayablesAsync(year, month);
    // Remove pay for anyone not yet employed this month BEFORE totals are summed.
    await PruneNotYetEmployedPayablesAsync(year, month);

    var instructorPayroll = monthPayrolls.Sum(p => p.TotalPayroll);
    var receptionistPayroll = await ComputeReceptionistPayrollCostAsync(year, month);
    var totalPayroll = instructorPayroll + receptionistPayroll;

    var totalNetBeforeAllocations = totalSales - totalPayroll - totalFixed - totalSalaries - totalDepreciation;

    // ── Allocation split (P2-S01) ───────────────────────────────────────
    var (mktPct, savPct, ownPct) = await _settings.GetEffectiveAllocationAsync(year, month);
    // When net is negative there is no profit to allocate to marketing or savings;
    // the entire shortfall falls on the owners pool.
    decimal marketingAllocation, savingsAllocation, ownersPool;
    if (totalNetBeforeAllocations < 0)
    {
        marketingAllocation = 0m;
        savingsAllocation = 0m;
        ownersPool = totalNetBeforeAllocations;
    }
    else
    {
        marketingAllocation = SafeMultiplyPct(totalNetBeforeAllocations, mktPct);
        savingsAllocation = SafeMultiplyPct(totalNetBeforeAllocations, savPct);
        ownersPool = SafeMultiplyPct(totalNetBeforeAllocations, ownPct);
    }

    // ── Persist washout ──────────────────────────────────────────────────
    var washout = new MonthlyWashout
    {
        // ObjectId-bound; must be either null (let driver generate) or a 24-char hex string.
        // String.Empty fails the BsonRepresentation parse.
        Id = existing?.Id,
        Month = month,
        Year = year,
        TotalSalesRevenue = totalSales,
        TotalEarnedRevenue = totalSales,
        TotalPayroll = totalPayroll,
        TotalFixedExpenses = totalFixed,
        TotalSalaries = totalSalaries,
        TotalCapitalDepreciation = totalDepreciation,
        TotalNetBeforeAllocations = totalNetBeforeAllocations,
        MarketingAllocation = marketingAllocation,
        SavingsAllocation = savingsAllocation,
        OwnersPool = ownersPool,
        MarketingPercentageApplied = mktPct,
        SavingsPercentageApplied = savPct,
        OwnersPercentageApplied = ownPct,
        RevenueByCategory = revenueByCategory,
        RevenueByMethod = revenueByMethod,
        NetIncome = totalNetBeforeAllocations, // backward-compat: pre-S03 callers expect this
        Locked = existing?.Locked ?? false,
        CalculatedAt = DateTime.UtcNow,
        CreatedAt = existing?.CreatedAt ?? DateTime.UtcNow,
        UpdatedAt = DateTime.UtcNow,
    };

    // Insert vs replace explicitly — ReplaceOneAsync with IsUpsert=true and a null/empty
    // Id ends up sending _id:null literally, which collides on the second compute.
