private async Task<StripeRoutingContext> ResolveStripeRoutingAsync(IEnumerable<Expense> monthExpenses)
{
    var settings = await _settings.GetAsync();
    if (settings.StripeRoutingMode != StripeRoutingModes.OwnerRouted)
    {
        return StripeRoutingContext.NotRouted;
    }
    var feeAmount = monthExpenses
        .Where(e => string.Equals(e.Category, StripeRoutingModes.FeeExpenseCategory, StringComparison.OrdinalIgnoreCase))
        .Sum(e => e.Amount);
    var routedOwner = await _ownerProfiles
        .Find(p => p.ReceivesStripePayouts == true && p.IsActiveOwner == true)
        .FirstOrDefaultAsync();
    if (routedOwner is null)
    {
        // Defensive: settings allowed OWNER_ROUTED but the owner roster has
        // since been edited. Fall back to company-account behaviour rather
        // than crashing the washout.
        return StripeRoutingContext.NotRouted;
    }
    return new StripeRoutingContext(true, routedOwner.StaffId, feeAmount);
}

/// <summary>Internal value passed from cost-computation into per-owner distribution emission.</summary>
private readonly record struct StripeRoutingContext(bool IsRouted, string? RoutedOwnerStaffId, decimal FeeAmount)
{
    public static readonly StripeRoutingContext NotRouted = new(false, null, 0);
}

private async Task<decimal> ComputeReceptionistPayrollCostAsync(int year, int month)
{
    var receptionistNames = (await _staffCollection
            .Find(s => s.Role == "RECEPTIONIST")
            .Project(s => s.Name)
            .ToListAsync())
        .Where(name => !string.IsNullOrWhiteSpace(name))
        .Select(name => name.Trim())
        .ToHashSet(StringComparer.OrdinalIgnoreCase);

    var monthRows = await _staffPayables
        .Find(x => x.Year == year && x.Month == month)
        .ToListAsync();

    return monthRows
        .Where(row =>
            receptionistNames.Contains(row.StaffName.Trim()) ||
            row.ReceptionistAttendanceCommissionAmount != 0m ||
            row.ReceptionistKpiBonusAmount != 0m)
        // Only the receptionist's commission + bonus belong to "payroll" here.
        // Their SALARY is already captured in totalSalaries (the salary-tagged
        // expense from the Monthly Salaries editor, which also populates
        // row.SalaryAmount). Including SalaryAmount again would double-count the
        // receptionist's salary — inflating payroll and dropping Net by that
        // amount on any recompute where the payable already carries the salary.
        .Sum(row => row.CommissionAmount + row.BonusAmount);
}

// ── Helpers ─────────────────────────────────────────────────────────────

/// <summary>
/// Groups invoice-line totals by the line's product Type (e.g. <c>"PACKAGE"</c>).
/// Lines with no resolvable product roll up under <c>"UNCATEGORISED"</c> rather
/// than silently disappearing — visibility wins over neatness here.
/// </summary>
private async Task<Dictionary<string, decimal>> ComputeRevenueByCategoryAsync(
    IEnumerable<Invoice> invoices, List<Payment> monthPayments)
{
    // Cash-basis: attribute each invoice's ACTUALLY-PAID amount (this period) to
    // its product categories, in proportion to each line's share of the invoice.
    // Invoices with no payment in the period contribute nothing.
    var paidByInvoice = monthPayments
        .GroupBy(p => p.InvoiceId)
        .ToDictionary(g => g.Key, g => g.Sum(p => p.AmountPaid));
    if (paidByInvoice.Count == 0) return new();

    var paidInvoices = invoices
        .Where(i => i.Id != null && paidByInvoice.ContainsKey(i.Id!))
        .ToList();

    var allLines = paidInvoices.SelectMany(i => i.Lines).ToList();
    if (allLines.Count == 0) return new();

    // Lines created after the P5 snapshot rollout carry their own
    // ProductTypeSnapshot. We only need to round-trip to Products for
    // the legacy tail — pre-snapshot lines whose ProductTypeSnapshot is
    // still null. This keeps historical washouts stable even after a
    // product is reclassified (the whole point of the snapshot), while
    // still attributing legacy lines to *something* sensible.
    var legacyProductIds = allLines
        .Where(l => string.IsNullOrWhiteSpace(l.ProductTypeSnapshot)
                 && !string.IsNullOrWhiteSpace(l.ProductId))
        .Select(l => l.ProductId)
        .Distinct()
        .ToList();
    var legacyTypeById = legacyProductIds.Count == 0
        ? new Dictionary<string, string>()
        : (await _products.Find(p => legacyProductIds.Contains(p.Id)).ToListAsync())
            .ToDictionary(p => p.Id!, p => p.Type ?? "UNCATEGORISED");

    string TypeOf(InvoiceLine l) =>
        !string.IsNullOrWhiteSpace(l.ProductTypeSnapshot)
            ? l.ProductTypeSnapshot!
            : legacyTypeById.GetValueOrDefault(l.ProductId ?? string.Empty, "UNCATEGORISED");

    var result = new Dictionary<string, decimal>();
    foreach (var inv in paidInvoices)
    {
        var paid = paidByInvoice[inv.Id!];
        if (paid == 0m || inv.Lines.Count == 0) continue;
        var lineSum = inv.Lines.Sum(l => l.LineTotal);
        foreach (var l in inv.Lines)
        {
            // Split the actually-paid amount across categories by each line's
            // share (any fee/tax on top of line totals is spread proportionally).
            var share = lineSum > 0 ? l.LineTotal / lineSum : 1m / inv.Lines.Count;
            var cat = TypeOf(l);
            result[cat] = result.GetValueOrDefault(cat) + Math.Round(paid * share);
        }
    }
    return result;
}

