// READ-ONLY. Recompute Aug-2026 washout revenue two ways to confirm the fix
// nets the online fee out (OLD sum(AmountPaid) vs NEW sum(AmountPaid*(1-ratio))),
// replicating BOTH AccountingService (post-fix) AND AnalyticsService netting.
const db = db.getSiblingDB("soulpilates");
const start = ISODate("2026-08-01T00:00:00.000Z");
const end   = ISODate("2026-09-01T00:00:00.000Z");
const num = v => (v && v.constructor && v.constructor.name === "Decimal128") ? parseFloat(v.toString()) : (typeof v === "number" ? v : parseFloat(v || 0));
const clamp = (x,a,b) => Math.max(a, Math.min(b, x));

const invs = db.Invoices.find({ IssueDate: { $gte: start, $lt: end }, Status: { $ne: "VOIDED" } })
  .project({ _id:1, OnlineFeeAmount:1, TotalNet:1 }).toArray();
const ratio = {}; let totalNet = 0, totalFeeOnInv = 0;
invs.forEach(i => {
  const net = num(i.TotalNet), fee = num(i.OnlineFeeAmount);
  ratio[i._id.toString()] = net > 0 ? clamp(fee/net, 0, 1) : 0;
  totalNet += net; totalFeeOnInv += fee;
});
const ids = invs.map(i => i._id);
const pays = db.Payments.find({ InvoiceId: { $in: ids }, PaymentDate: { $gte: start, $lt: end } })
  .project({ InvoiceId:1, AmountPaid:1, PaymentMethod:1 }).toArray();

let oldRev = 0, newRev = 0, feeNetted = 0;
const oldByMethod = {}, newByMethod = {};
pays.forEach(p => {
  const amt = num(p.AmountPaid);
  const r = ratio[p.InvoiceId.toString()] ?? 0;
  const net = amt * (1 - r);
  oldRev += amt; newRev += net; feeNetted += amt * r;
  const m = p.PaymentMethod || "UNKNOWN";
  oldByMethod[m] = (oldByMethod[m]||0) + amt;
  newByMethod[m] = (newByMethod[m]||0) + net;
});
print("Aug-2026 window [" + start.toISOString() + ", " + end.toISOString() + ")");
print("invoices(non-voided)=" + invs.length + "  payments=" + pays.length);
print("SUM invoice OnlineFeeAmount = " + totalFeeOnInv);
print("OLD totalSales (sum AmountPaid, fee counted)      = " + oldRev);
print("NEW totalSales (sum AmountPaid*(1-ratio), netted) = " + Math.round(newRev*100)/100);
print("fee netted out of revenue                         = " + Math.round(feeNetted*100)/100);
print("revenueByMethod OLD = " + JSON.stringify(oldByMethod));
print("revenueByMethod NEW = " + JSON.stringify(Object.fromEntries(Object.entries(newByMethod).map(([k,v])=>[k,Math.round(v*100)/100]))));

